<div id="scroll-animate">
    <div id="scroll-animate-main">
        <div class="wrapper-parallax">
            <!-- header -->
            <header class="nav-head">
                <h1>به التا خوش آمدید</h1>
                <h3>اولین و تخصصی ترین پلتفرم فریلنسری در ایران</h3>
            </header>
